def transform(grid):
    h, w = len(grid), len(grid[0])

    from collections import Counter

    base = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Grid separators have relatively few cells of the main fill color.
    row_candidates = [r for r in range(h) if sum(v == base for v in grid[r]) < w * 0.5]
    col_candidates = [
        c for c in range(w)
        if sum(grid[r][c] == base for r in range(h)) < h * 0.5
    ]

    if not row_candidates or not col_candidates:
        return [[base]]

    # The most common color on separator lines is their background color.
    line_color = Counter(
        grid[r][c] for r in row_candidates for c in range(w)
    ).most_common(1)[0][0]

    # Keep separator coordinates that contain a marker distinct from both
    # the separator background and the main fill.
    rows = [
        r for r in row_candidates
        if any(v != base and v != line_color for v in grid[r])
    ]
    cols = [
        c for c in col_candidates
        if any(grid[r][c] != base and grid[r][c] != line_color for r in range(h))
    ]

    out = []
    for r1, r2 in zip(rows, rows[1:]):
        out_row = []
        for c1, c2 in zip(cols, cols[1:]):
            corners = [
                grid[r1][c1], grid[r1][c2],
                grid[r2][c1], grid[r2][c2]
            ]
            if corners[0] not in (base, line_color) and all(v == corners[0] for v in corners):
                out_row.append(corners[0])
            else:
                out_row.append(base)
        out.append(out_row)

    return out
